CREATE OR REPLACE FUNCTION public.personas_club() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('email',e.email,'nombre',e.nombre,'activo',coalesce(u.email_confirmed_at IS NOT NULL,false),'roles',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) FROM public.usuario_roles r WHERE lower(r.email)=e.email AND r.activo))),'[]'::jsonb) FROM (SELECT email,max(nombre) nombre FROM (SELECT lower(email) email,nombre FROM public.usuario_roles UNION ALL SELECT lower(email),nombre FROM public.socios WHERE email IS NOT NULL UNION ALL SELECT lower(email),nombre FROM public.profiles WHERE email IS NOT NULL UNION ALL SELECT lower(email),coalesce(raw_user_meta_data->>'full_name','') FROM auth.users WHERE email IS NOT NULL) x GROUP BY email) e LEFT JOIN auth.users u ON lower(u.email)=e.email); END $$;